// Multicast CE copy is only supported with CUDA 13.1+
static bool multicastCEFilter(CopyType copyType) {
    if (copyType != COPY_TYPE_CE) {
        return true;
    }

    int driverVersion = 0;
    CU_ASSERT(cuDriverGetVersion(&driverVersion));
    return driverVersion >= 13010;
}

